import{_ as t,c as n,o as r,ai as o}from"./chunks/framework.BCiyC5yl.js";const c=JSON.parse('{"title":"MCK Meeting Series","description":"","frontmatter":{"title":"MCK Meeting Series","date":"2026-07-21","banner":"assets/events/20260721_mck_neonephos_series_banner.svg","bannerMobile":"assets/events/20260721_mck_neonephos_series_banner_mobile.svg","bannerSmall":"assets/events/20260721_mck_neonephos_series_banner_small.svg","backgroundhex":"#128256ff","tags":["neonephos","mck","ipcei"],"published":true,"sidebar":false,"aside":false,"prev":false,"next":false,"layout":"EventEntryThemeComponent"},"headers":[],"relativePath":"events/2026_07_21_MCK_Meeting_Series.md","filePath":"events/2026_07_21_MCK_Meeting_Series.md"}'),s={name:"events/2026_07_21_MCK_Meeting_Series.md"};function i(a,e,l,h,_,d){return r(),n("div",null,e[0]||(e[0]=[o('<h1 id="neonephos-meeting-series" tabindex="-1">NeoNephos Meeting Series <a class="header-anchor" href="#neonephos-meeting-series" aria-label="Permalink to &quot;NeoNephos Meeting Series&quot;">​</a></h1><p>It&#39;s MCK time! The next IPCEI-CIS Workstream 2 Multi Cluster Kubernetes (MCK) meeting session will be held on the <strong>21th of July from 10:00-11:30 am CET</strong>.</p><p>Agenda:</p><ul><li>40 min: <strong>Bring Your Own Cluster: Hosting a Sovereign Workload Anywhere in the EU</strong>: Digital sovereignty means running your workloads where you choose, under your own control, without being locked into a single provider. This session introduces the Apeiro Showroom, the integration environment where Apeiro components are brought together into one working landscape, and gives a short recap of Platform Mesh, the multi tenant orchestration layer that lets consumers order and consume services from different providers through one consistent, Kubernetes-native interface. The main part is a live demo of SimpleCluster, our Bring Your Own Cluster scenario: a Kubernetes cluster is ordered like any other service, whether provisioned by a European cloud provider or brought along self-hosted, and a sovereign LLM chat service is deployed onto it as an example workload. Cluster provider and workload are deliberately interchangeable; the point is the open, provider-neutral consumption path Apeiro enables: the same journey, wherever you host.</li></ul><hr><p>👉 As always, join the meeting <a href="https://teams.microsoft.com/l/meetup-join/19%3ameeting_NjgzOGUxNTItYjBjYy00NWZlLThkMjktNGZhMzM0NTg3MjZl%40thread.v2/0?context=%7b%22Tid%22%3a%2242f7676c-f455-423c-82f6-dc2d99791af7%22%2c%22Oid%22%3a%22f448159f-8442-4772-945c-ad5c1d621625%22%7d" target="_blank" rel="noreferrer">here</a>.</p>',6)]))}const m=t(s,[["render",i]]);export{c as __pageData,m as default};
